// src/app/auth-guard.ts
var alumniGuard = () => {
  const router = inject2(Router);
  const userId = localStorage.getItem("userId");
  const role = localStorage.getItem("role");
  if (userId) {
    if (role === "alumni") {
      return true;
    } else if (role === "admin") {
      router.navigate(["/admin"]);
      return false;
    }
  }
  router.navigate(["/login"]);
  return false;
};
var adminGuard = () => {
  const router = inject2(Router);
  const userId = localStorage.getItem("userId");
  const role = localStorage.getItem("role");
  if (userId) {
    if (role === "admin") {
      return true;
    } else if (role === "alumni") {
      router.navigate(["/portal"]);
      return false;
    }
  }
  router.navigate(["/login"]);
  return false;
};

