var routes = [
  // Public Routes
  { path: "", component: Home },
  { path: "login", component: Login },
  { path: "register", component: Register },
  { path: "resetpassword", component: ForgotPassword },
  //  Role-Protected Internal Workspaces
  {
    path: "portal",
    component: Portal,
    canActivate: [alumniGuard]
    // Only allows matching Alumni members
  },
  {
    path: "admin",
    component: Admin,
    canActivate: [adminGuard]
    //  Only allows matching System Administrators
  }
];

