var environment = {
  production: true,
  apiUrl: "http://192.168.0.115:8080/admin.php"
};

// src/app/core/interceptors/api-interceptor.ts
var apiInterceptor = (req, next) => {
  const isAbsoluteUrl2 = req.url.startsWith("http://") || req.url.startsWith("https://");
  if (!isAbsoluteUrl2) {
    const clonedRequest = req.clone({
      url: `${environment.apiUrl}${req.url.startsWith("/") ? "" : "/"}${req.url}`
    });
    return next(clonedRequest);
  }
  return next(req);
};

// src/app/app.config.ts
